   (	"ID" NUMBER,
	"TEMPLATECODE" VARCHAR2(120 BYTE),
	"TEMPLATENAME" VARCHAR2(120 BYTE),
	"TEMPLATETYPE" VARCHAR2(60 BYTE),
	"TEMPLATEFILEID" NUMBER,
	"TEMPLATEFILENAME" VARCHAR2(120 BYTE),
	"TEMPLATEMODALTYPE" VARCHAR2(30 BYTE),
	"PARAM" VARCHAR2(60 BYTE),
	"REMARK" VARCHAR2(450 BYTE),
	"CREATEDBYID" VARCHAR2(36 BYTE),
	"CREATEDBYNAME" VARCHAR2(60 BYTE),
	"CREATEDTIME" DATE,
	"CREATEDBYORGID" VARCHAR2(36 BYTE),
	"CREATEDBYORGNAME" VARCHAR2(270 BYTE),
	"ACTIVATEDFLAG" VARCHAR2(36 BYTE),
	"ACTIVATEDBYID" VARCHAR2(36 BYTE),
	"ACTIVATEDBYNAME" VARCHAR2(60 BYTE),
	"ACTIVATEDTIME" DATE,
	"DEFAULTVALUE" VARCHAR2(360 BYTE),
	 CONSTRAINT "PK_LIMS_REPORT_TEMPLATE" PRIMARY KEY ("ID")
  USING INDEX  ENABLE
   );
-- END OBJECT TABLE T_LIMS_REPORT_TEMPLATE

